def line_up(name, number):
    n = int(number)
    # special case for 11, 12, 13
    if 10 <= (n % 100) <= 13:
        suffix = "th"
    else:
        last = n % 10
        if last == 1:
            suffix = "st"
        elif last == 2:
            suffix = "nd"
        elif last == 3:
            suffix = "rd"
        else:
            suffix = "th"
    return f"{name}, you are the {n}{suffix} customer we serve today. Thank you!"
